diff --git a/src/pcre2posix.c b/src/pcre2posix.c
index 2f2cdf54..bc824f0a 100644
--- a/src/pcre2posix.c
+++ b/src/pcre2posix.c
@@ -412,6 +412,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
       return REG_INVARG;
     so = (PCRE2_SIZE)pmatch[0].rm_so;
     eo = (PCRE2_SIZE)pmatch[0].rm_eo;
+    string += so;
   }
   else
   {
@@ -419,7 +420,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     eo = strlen(string);
   }

-  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string + so, (eo - so), 0,
+  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string, (eo - so), 0,
                    options, md, NULL);

   /* Successful match */

diff --git a/src/pcre2posix.c b/src/pcre2posix.c
index 401ad0ab..bd7ad786 100644
--- a/src/pcre2posix.c
+++ b/src/pcre2posix.c
@@ -422,8 +422,9 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t

   /* REG_STARTEND is a BSD extension, to allow for non-NUL-terminated strings.
   The man page from OS X says "REG_STARTEND affects only the location of the
-  string, not how it is matched". That is why the "so" value is used to bump the
-  start location rather than being passed as a PCRE2 "starting offset". */
+  string, not how it is matched". Once the offsets have been checked, the "so"
+  value can be handed to PCRE2 as the starting offset, with "eo" giving the end
+  of the subject. */

   if ((eflags & REG_STARTEND) != 0)
   {
@@ -433,6 +434,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
       return REG_INVARG;
     so = (PCRE2_SIZE)pmatch[0].rm_so;
     eo = (PCRE2_SIZE)pmatch[0].rm_eo;
+    string += so;
   }
   else
   {
@@ -440,7 +442,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     eo = strlen(string);
   }

-  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string + so, (eo - so), 0,
+  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string, eo, so,
                    options, md, NULL);

   /* Successful match */
@@ -453,16 +455,16 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
       rc = (int)nmatch;
     for (i = 0; i < (size_t)rc; i++)
     {
-      if (ovector[i * 2] == PCRE2_UNSET || ovector[i * 2] + so > (PCRE2_SIZE)INT_MAX ||
-          ovector[i * 2 + 1] == PCRE2_UNSET || ovector[i * 2 + 1] + so > (PCRE2_SIZE)INT_MAX)
+      if (ovector[i * 2] == PCRE2_UNSET || ovector[i * 2] > (PCRE2_SIZE)INT_MAX ||
+          ovector[i * 2 + 1] == PCRE2_UNSET || ovector[i * 2 + 1] > (PCRE2_SIZE)INT_MAX)
       {
         pmatch[i].rm_so = -1;
         pmatch[i].rm_eo = -1;
       }
       else
       {
-        pmatch[i].rm_so = (int)(ovector[i * 2] + so);
-        pmatch[i].rm_eo = (int)(ovector[i * 2 + 1] + so);
+        pmatch[i].rm_so = (int)ovector[i * 2];
+        pmatch[i].rm_eo = (int)ovector[i * 2 + 1];
       }
     }
